+void LookAtModifier3D::set_target_node(NodePath p_target_node) {
+	if (target_node != p_target_node) {
+		init_transition();
+	}
+	target_node = p_target_node;
+}
+
+NodePath LookAtModifier3D::get_target_node() const {
