+// For time-based interpolation.
+
+void LookAtModifier3D::set_duration(float p_duration) {
+	duration = p_duration;
+	if (Math::is_zero_approx(p_duration)) {
+		time_step = 0;
+		remain = 0;
+	} else {
+		time_step = 1.0 / p_duration;
+	}
+}
